const raw = $input.first().json.body;
const body = typeof raw === 'string' ? JSON.parse(raw) : (raw || {});
const msg = String(body.message || '').trim().slice(0, 1000);
let reply = 'Olá! Posso ajudar-te a encontrar jogos de futebol, futsal, basquetebol e padel, ou a organizar uma partida. Para informações sobre uma inscrição, indica o jogo e o teu email (não partilhes palavras-passe).';
const q = msg.toLocaleLowerCase('pt-PT');
if (!msg) reply = 'Escreve a tua pergunta para podermos ajudar.';
else if (/preç|cust|pagament|quanto/.test(q)) reply = 'O preço indicado em cada jogo é por pessoa. Confirma as condições com o organizador antes de pagar.';
else if (/inscri|reserv|particip|vaga/.test(q)) reply = 'Escolhe um jogo e clica em «Quero jogar». O teu pedido será enviado para análise; a inscrição só fica confirmada após resposta da organização.';
else if (/criar|organizar|publicar/.test(q)) reply = 'Clica em «Criar jogo», escolhe a modalidade, local, data, hora e número de participantes, e envia o pedido.';
else if (/cancel|desist/.test(q)) reply = 'Para cancelar, contacta a organização do jogo. Esta versão de demonstração ainda não tem cancelamentos automáticos.';
return [{json:{reply,sessionId:String(body.sessionId||''),mode:'faq-demo'}}];
